UPDATE blog_posts SET localizations = coalesce(localizations, '{}'::jsonb) || jsonb_build_object('excerptZhHant', '溫哥華業主正在將後院改造成全年可用的戶外生活空間。本指南涵蓋2026年甲板、露台和有頂戶外區域的裝修費用及大溫哥華各城市的許可要求。'::text) WHERE id = '247e6fde-08dc-4285-b5c7-bbe236069047' AND NOT (coalesce(localizations, '{}'::jsonb) ? 'excerptZhHant');
