UPDATE faqs SET localizations = coalesce(localizations, '{}'::jsonb) || jsonb_build_object('answerZhHant', '是的 — Port Coquitlam要求完整的建築許可證及二級套間檢查。套間必須滿足防火隔離、緊急出口窗戶和最低淨高要求。Reno Stars全程管理這一申請流程。'::text) WHERE id = '63108857-5571-4865-8abf-5520bc086a87' AND NOT (coalesce(localizations, '{}'::jsonb) ? 'answerZhHant');
